VALUES ('zheng-r0', '友', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '周宣王封弟友于郑，任周室司徒。前771年犬戎陷镐京，桓公遇害，子掘突继位为武公，郑国迁于中原。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑桓公"}]'::jsonb, '桓公', NULL, '郑桓公')
