VALUES ('zheng-r10', '子兰', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文公之子，灵公之弟。弑兄即位，在列国间周旋，维系郑国在中原的存续，国势尚可，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑穆公"}]'::jsonb, '穆公', NULL, '郑穆公')
