VALUES ('zheng-r13', '沸', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位不足两年，遭兄釐公内乱而被弑，郑国政局继续动荡不安，无力外争，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑悼公"}]'::jsonb, '悼公', NULL, '郑悼公')
