VALUES ('zheng-r14', '睔', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '执政期间郑国夹缝于晋楚之间，多次遣使盟楚，在列国间艰难周旋求存，国势渐弱，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑成公"}]'::jsonb, '成公', NULL, '郑成公')
