VALUES ('zheng-gongzi-xu', '繻', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '公子繻，郑国君主。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/公子繻"}]'::jsonb, NULL, NULL, '公子繻')
