VALUES ('zheng-r15', '恽', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位五年而卒，末代君主中郑国局面尚可维持，但已无力争霸，仰息于晋楚，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑釐公"}]'::jsonb, '釐公', NULL, '郑釐公')
