VALUES ('zheng-r16', '嘉', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位三十五年，郑国已沦为二流小国，仰息于晋楚等强邻之间，无力外争，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑简公"}]'::jsonb, '简公', NULL, '郑简公')
