VALUES ('zheng-r17', '宁', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '孔子弟子子产执政之年，修城施政、作刑鼎，郑国稍得整顿，国势略有回升，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑定公"}]'::jsonb, '定公', NULL, '郑定公')
