VALUES ('zheng-r18', '趸', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '定公之弟，弑兄自立。在位十二年而亡，郑国继续衰落，无力维持大国地位，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑献公"}]'::jsonb, '献公', NULL, '郑献公')
