VALUES ('zheng-r19', '胜', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位三十八年，郑国名存实亡，仅守新郑一地，无力外争，仰息于韩等强邻，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑声公"}]'::jsonb, '声公', NULL, '郑声公')
