VALUES ('zheng-r20', '易', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位仅七年，为共公之弟所弑，郑国内乱不止，国势奄奄一息，无力维持，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑哀公"}]'::jsonb, '哀公', NULL, '郑哀公')
