VALUES ('zheng-r21', '丑', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位三十年，郑国式微，无力外争，仰息于韩等强邻，维持小国局面，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑共公"}]'::jsonb, '共公', NULL, '郑共公')
