VALUES ('zheng-r22', '已', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位不足一年，为𦈡公所弑，郑国濒临灭亡，政局极度动荡，国势危急，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑幽公"}]'::jsonb, '幽公', NULL, '郑幽公')
