VALUES ('zheng-r23', '骀', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '弑幽公自立，在位二十七年。郑国已濒临灭亡，无力抵抗韩国，国势危急，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑𦈡公"}]'::jsonb, '𦈡公', NULL, '郑𦈡公')
