VALUES ('zheng-r24', '乙', ARRAY[]::text[], '姬', '郑', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '郑国末代君主。前375年为韩武子所灭，国亡，郑国历史终结，姬姓郑国不复存在，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑康公"}]'::jsonb, '康公', NULL, '郑康公')
